// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock reports the current time. It is an interface so tests can inject a
// fake clock.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system wall clock.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter. A Limiter starts
// full and refills at Rate tokens per second, up to a burst of Burst tokens.
// The zero value is not usable; construct with New.
type Limiter struct {
	mu       sync.Mutex
	rate     float64 // tokens per second
	burst    int     // bucket capacity
	tokens   float64 // current tokens
	lastFill time.Time
	clock    Clock
}

// Errors returned by New.
var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New returns a Limiter that emits tokens at rate tokens per second with a
// maximum burst capacity. The bucket starts full. clock is injectable for
// testing; pass RealClock() (or nil, which defaults to the real clock) in
// production.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || math.IsNaN(rate) || math.IsInf(rate, 0) {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		clock = RealClock()
	}
	now := clock.Now()
	return &Limiter{
		rate:     rate,
		burst:    burst,
		tokens:   float64(burst),
		lastFill: now,
		clock:    clock,
	}, nil
}

// Allow reports whether n tokens are available at the current time.
// It is shorthand for AllowN(now, n) using the limiter's clock.
func (l *Limiter) Allow(n int) bool {
	return l.AllowN(l.clock.Now(), n)
}

// AllowN reports whether n tokens are available at time now, consuming them
// if so. now must be monotonically non-decreasing across calls; if it moves
// backward, no refill credit is granted. If n exceeds the burst capacity,
// AllowN returns false without consuming tokens.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill based on elapsed time since the last fill.
	if elapsed := now.Sub(l.lastFill); elapsed > 0 {
		l.tokens = math.Min(float64(l.burst), l.tokens+elapsed.Seconds()*l.rate)
		l.lastFill = now
	}

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Rate returns the configured refill rate in tokens per second.
func (l *Limiter) Rate() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.rate
}

// Burst returns the configured bucket capacity.
func (l *Limiter) Burst() int {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.burst
}
