func TestConcurrentAccess(t *testing.T) {
	fc := newFakeClock(time.Unix(0, 0))
	l, err := New(1000, 100, fc)
	if err != nil {
		t.Fatalf("New() error: %v", err)
	}
	var wg sync.WaitGroup
	allowed := make(chan struct{}, 1000)
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow(1) {
				allowed <- struct{}{}
			}
		}()
	}
	wg.Wait()
	close(allowed)
	if n := len(allowed); n != 100 {
		t.Fatalf("concurrent Allow: %d allowed, want 100 (full bucket)", n)
	}
}
